bq = kb5 / (1.0 + getw(5, 'self_attn.q_norm')); bq = bq / np.linalg.norm(bq)             # pre-norm query direction that becomes parallel to bos key after q_norm weights
def Wq5_edit(heads_, gamma, qpre_typ=15.0):
    Wn = Wq5.copy()
    for h_ in heads_: Wn[h_*256:(h_+1)*256] += gamma * qpre_typ * np.outer(bq, a5)
    return Wn
