# Hypothesis: the key edit at blocks 7/9/10 removes attention to the guess token and returns part of it to the question in T and A, leaving N unchanged.
def key_edit(l, u, beta, train):
    pre = f'model.layers.{l}.'
    Wk0 = load(pre+'self_attn.k_proj.weight'); win = W(pre+'input_layernorm.weight')
    keysG, sG, bos = [], [], []
    for k, p in train:
        x, lab = rows_for(l, k, p)
        if (lab==1).any():
            keysG.append((x[lab==1] @ Wk0.T).norm(dim=-1)); sG.append(x[lab==1] @ u)
        bos.append(x[0] @ Wk0.T)
    nrm = float(torch.cat(keysG).mean()); sg = float(torch.cat(sG).mean()); b = torch.stack(bos).mean(0); bhat = b / b.norm()
    return Wk0 - (beta*nrm/sg) * torch.outer(bhat, u), dict(u=u, bhat=bhat, nrm=nrm, sG=sg)
def predict_block(l, Wk_new, grp, Wq_new=None):
    out = {}
    for cn in COND:
        base = np.zeros((4, 6)); new = np.zeros((4, 6)); tv = np.zeros(4)
        for fi in grp:
            i = fi*3 + COND.index(cn); p = dec_pos[(fi,cn)]; cat = cat_masks(fi, cn)[:p+1]
            x = torch.tensor(np.array(H16[l][i]))
            a0 = np.array(ATT16[l][i,:,p,:p+1]); a1 = attn_recon(l, x, x[p], p, Wq=Wq_new, Wk=Wk_new).numpy()
            for h in range(4):
                base[h] += cat_sums(a0[h], cat); new[h] += cat_sums(a1[h], cat)
            tv += 0.5*np.abs(a1-a0).sum(-1)
        out[cn] = (base/len(grp), new/len(grp), tv/len(grp))
    return out
odd = [fi for fi in range(50) if fi%2==1]
trainfit = [(k, p) for k, p in allp if (tpl_code(p) in ('T','A') and p['fi']%2==0) or tpl_code(p) in ('C','B')]
