The installed probes generalize poorly to new kinds and phrasings. At block 7 guess tokens score only 0.46 ± 0.59 while tokens of ordinary new messages have an rms of 0.46, so there the edit is mostly noise. Blocks 9 and 10 give 0.61 and 0.70 against noise 0.32 and 0.30, and blocks 11 and 12 give 0.61 and 0.78 against noise 0.12 and 0.23. So the current edit both under-detects new guesses and perturbs ordinary questions, which fits the damage seen on counting questions.

Next I refit with everything (old dev-fact data, the 115 no-guess facts, and the 239 new texts) and select the ridge strength by 4-fold validation. Each fold holds out a group of fact kinds, a quarter of the phrasings and a quarter of the negative messages together, and I report the guess score on texts whose kind and phrasing were both unseen, and the leak on unseen negatives. The target is a guess score well above 0.6 with leak rms several times below the current values.

```python
# Hypothesis: refit with diverse data gives held-out G >> leak (e.g. G~0.7, leak rms ~0.1) at all blocks; pick ridge by 4-fold CV
kind_fold = {'count':0,'science':1,'animal':1,'country':2,'grammar':2,'arith2':3,'capital':3,'opposite':0,'misc':1,'ho1':None}
def build_rows2(l):
    X, y, tags = DS[l]
    Xs, ys, tg = [X], [y], list(tags)
    newX, newy = [], []
    for s in S21:
        x = in_norm(l, H21[l][s['i'], :s['L']]).double()
        for p in range(s['L']):
            isg = p in s['gspan']
            newX.append(x[p]); newy.append(1.0 if isg else 0.0)
            tg.append((21, s['tpl'], s['i'], 'G' if isg else ('bos' if p==0 else 'o'), s['kind']))
    return torch.cat([X, torch.stack(newX)]), torch.cat([y, torch.tensor(newy).double()]), tg
DS2 = {l: build_rows2(l) for l in [7,9,10,11,12]}
def fold_masks(tags):
    n = len(tags); te = np.zeros((4, n), bool); both = np.zeros((4, n), bool)
    for r, t in enumerate(tags):
        st, ph, idx, cat, kind = t
        for f in range(4):
            if st == 21:
                if kind == 'neg':
                    if idx % 4 == f: te[f, r] = True
                else:
                    kf = kind_fold[kind] == f; pf = (PH2.index(ph) % 4 == f)
                    if kf or pf: te[f, r] = True
                    if kf and pf: both[f, r] = True
            elif st == 20:
                kk = kind_fold.get(kind)
                if kk == f or (kind == 'ho1' and idx % 4 == f): te[f, r] = True
    return te, both
def cv2(l, rel_lams=(1e-3,3e-3,1e-2,3e-2,1e-1,3e-1), posw_ratio=1.0, verbose=True):
    X, y, tags = DS2[l]
    te, both = fold_masks(tags)
    cat = np.array([t[3] for t in tags])
    npos, nneg = float(y.sum()), float((1-y).sum())
    w = torch.where(y > 0, torch.tensor(posw_ratio*nneg/npos, dtype=torch.double), torch.tensor(1.0, dtype=torch.double))
    scale = float(((X * w[:, None]) * X).sum()) / 640
    res = {}
    for rl in rel_lams:
        G_all, G_both, leak = [], [], []
        for f in range(4):
            m = torch.tensor(te[f])
            u = ridge(X[~m], y[~m], w[~m], rl*scale)
            s = X[m] @ u; yy = y[m]
            G_all.append(s[yy > 0]); leak.append(s[(yy == 0) & torch.tensor(cat[te[f]] != 'bos')])
            mb = torch.tensor(both[f]); sb = X[mb] @ u; G_both.append(sb[y[mb] > 0])
        G_all, G_both, leak = torch.cat(G_all), torch.cat(G_both), torch.cat(leak)
        res[rl] = (float(G_all.mean()), float(G_all.std()), float(G_both.mean()), float(G_both.std()), float(G_both.min()), float((G_both<0.4).double().mean()),
                   float(leak.pow(2).mean().sqrt()), float(leak.abs().quantile(.99)), float(leak.abs().max()))
        if verbose:
            r = res[rl]
            print(f'  b{l} rl={rl:g}: G held-out {r[0]:.2f}+-{r[1]:.2f} | G new kind&phrasing {r[2]:.2f}+-{r[3]:.2f} min {r[4]:.2f} frac<0.4 {r[5]:.2f} | leak rms {r[6]:.3f} p99 {r[7]:.2f} max {r[8]:.2f} | d\' {r[2]/r[6]:.1f}')
    return res
CV2 = {l: cv2(l) for l in [7,9,10,11,12]}
