With raw hidden states and explicit original weights the reconstruction matches the recorded attention to 5e-7, so my offline attention predictions for a single block are exact. Now I fit the final probes on all data with relative ridge 0.03, plus the four fold-specific probes for honest held-out estimates. Then, per block, I compute the dose-response of the key edit at strengths β from 0.5 to 1.5. On the 115 no-guess texts I measure how much the attention of each head at the reply's answer position shifts (total variation), using for every text the probe from the fold that never saw its kind. On dev guess prompts I measure the attention mass left on the guess tokens. The old probe at β = 1 is the reference. I expect the refit probes to cut no-guess disturbance substantially at equal guess suppression.

```python
# Hypothesis: refit K edits disturb no-guess attention much less than the old ones at equal guess suppression (offline, single-block)
def fit_final(l, rl=0.03, exclude=None):
    X, y, tags = DS2[l]
    npos, nneg = float(y.sum()), float((1-y).sum())
    w = torch.where(y > 0, torch.tensor(nneg/npos, dtype=torch.double), torch.tensor(1.0, dtype=torch.double))
    scale = float(((X * w[:, None]) * X).sum()) / 640
    if exclude is not None:
        m = torch.tensor(~exclude); u = ridge(X[m], y[m], w[m], rl*scale)
    else:
        u = ridge(X, y, w, rl*scale)
    sG = float((X[y > 0] @ u).mean())
    return u.float(), sG
te_masks, _ = fold_masks(DS2[7][2])
U_new, U_fold = {}, {}
for l in [7,9,10,11,12]:
    U_new[l] = fit_final(l)
    U_fold[l] = [fit_final(l, exclude=te_masks[f]) for f in range(4)]
    print(l, 'final probe in-sample sG %.3f |u| %.3f ; old |u| %.3f ; cos(old,new) %.2f' % (U_new[l][1], U_new[l][0].norm(), old_u[l].norm(), float(torch.dot(U_new[l][0], old_u[l].float())/(U_new[l][0].norm()*old_u[l].norm()))))
old_info = {7: K_FINAL[7], 9: K_FINAL[9], 10: K_FINAL[10], 11: kp[11], 12: kp[12]}
def make_Wk(l, u, sG, beta):
    info_ = old_info[l]
    return Wk0[l] - beta * (info_['nrm'] / sG) * torch.outer(info_['bhat'].float(), u.float())
def text_fold20(i):
    k = ALLF[i]['kind'] if i >= 42 else 'ho1'
    return (i % 4) if k == 'ho1' else kind_fold[k]
A_rec20 = {l: np.load(F20+f'attn_{l}.npy') for l in [7,9,10,11,12]}
def n_tv(l, mode, beta):
    Wq_cur = load(f'model.layers.{l}.self_attn.q_proj.weight')
    tvs = []
    for i in range(115):
        L = lens20[i]; hh = H20[l][i, :L]; qp = A20[i][2] - 1
        qps = [qp] + ([qp+1] if toks20[i][qp+1] == 236743 else [])
        if mode == 'old': Wk = make_Wk(l, old_u[l], old_info[l]['sG'], beta)
        elif mode == 'new_cv': u, sG = U_fold[l][text_fold20(i)]; Wk = make_Wk(l, u, sG, beta)
        else: u, sG = U_new[l]; Wk = make_Wk(l, u, sG, beta)
        for q_ in qps:
            a0 = torch.as_tensor(attn_recon(l, hh, hh[q_], q_, Wq_cur, Wk0[l])).reshape(4, -1)
            a1 = torch.as_tensor(attn_recon(l, hh, hh[q_], q_, Wq_cur, Wk)).reshape(4, -1)
            tvs.append(0.5 * (a1 - a0).abs().sum(-1))
    T = torch.stack(tvs)
    return T.mean(0), T.max(0).values, T
for l in [7,9,10,11,12]:
    m_old, mx_old, _ = n_tv(l, 'old', 1.0)
    print(f'b{l} N attention TV per head (mean | max over texts): OLD b=1  {[round(x,2) for x in m_old.tolist()]} | {[round(x,2) for x in mx_old.tolist()]}')
    for beta in [0.5, 1.0, 1.5]:
