```python
# Fit combined K probe (DS2 + AUX) with weighted ridge (no intercept); CV on held-out facts / held DS2 rows.
def ridge_fit(X_, y_, w_, rl):
    Xw = X_ * w_[:, None]
    A_ = X_.T @ Xw
    lam_ = rl * np.trace(A_) / X_.shape[1]
    return np.linalg.solve(A_ + lam_ * np.eye(X_.shape[1]), Xw.T @ y_)
def make_set(l_):
    X2, y2, _ = DS2[l_]; X2 = np.asarray(X2, dtype=np.float64); y2 = np.asarray(y2, dtype=np.float64)
    Xa = AUX[l_].astype(np.float64); ya = (AUX_lab == 'G').astype(np.float64)
    X_ = np.concatenate([X2, Xa]); y_ = np.concatenate([y2, ya])
    tag = np.concatenate([np.array(['2' + c for c in cat]), np.array(['a' + c for c in AUX_lab])])
    hold = np.concatenate([np.asarray(held), AUX_fact % 2 == 1])
    return X_, y_, tag, hold
def weights(tag, y_, w_op, w_q, w_aux=1.0):
    w = np.ones(len(tag))
    w[tag == 'aOP'] = w_op; w[tag == '2Q'] = w_q; w[tag == 'au'] = w_q
    w[np.char.startswith(tag, 'a')] *= w_aux
    pos = y_ > 0.5
    w[pos] *= w[~pos].sum() / w[pos].sum()
    return w / w.sum()
def report(s, tag, mask):
    out = []
    for c in ['2G', 'aG', 'aOP', '2Q', 'au', '2o', 'ar']:
        m_ = (tag == c) & mask
        out.append('%s %.2f/%.2f' % (c, s[m_].mean(), np.sqrt((s[m_] ** 2).mean()) if not c.endswith('G') else s[m_].min()))
    return ' '.join(out)
SETS2 = {l_: make_set(l_) for l_ in BL}
print('columns: mean/rms (for G: mean/min) on HELD-OUT rows, average of the two folds shown separately')
