    for (w_op, w_q, rl) in [(1, 1, 0.03), (10, 1, 0.03), (30, 3, 0.03), (30, 3, 0.01), (100, 3, 0.03), (30, 3, 0.1)]:
        w = weights(tag, y_, w_op, w_q)
        for tr, te in [(~hold, hold), (hold, ~hold)]:
            u_ = ridge_fit(X_[tr], y_[tr], w[tr] / w[tr].sum(), rl)
            print('L%d wop %d wq %d rl %.2f | %s' % (l_, w_op, w_q, rl, report(X_[te] @ u_, tag, te)))
